command:
$ErrorActionPreference='Stop'
uv run --offline --frozen --no-sync ruff format scripts/generate_canonical_state.py tests/contract/test_canonical_state_current.py
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
uv run --offline --frozen --no-sync python -B scripts/generate_canonical_state.py
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
uv run --offline --frozen --no-sync python -B -m pytest tests/contract/test_canonical_state_current.py tests/contract/test_coverage_floor_is_stated_once.py -q -p no:cacheprovider
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
uv run --offline --frozen --no-sync ruff check scripts/generate_canonical_state.py tests/contract/test_canonical_state_current.py
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
uv run --offline --frozen --no-sync ruff format --check scripts/generate_canonical_state.py tests/contract/test_canonical_state_current.py
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
uv run --offline --frozen --no-sync mypy --follow-imports=silent scripts/generate_canonical_state.py
